#include "orbits/continuation_refinement.hpp"
#include "runtime/interpreter.hpp"
#include <chrono>
#include <cmath>
#include <iostream>
using namespace penta;
namespace {int checks=0;void check(bool ok,const char* text){++checks;if(!ok)throw std::runtime_error(text);}language::OdeDefinition model(const char* source){const auto result=language::analyse(source);if(!result.ok())throw std::runtime_error("Continuation fixture did not parse.");return *result.program.statements.front().ode;}}
int main(int argc,char** argv){
    const auto directory=std::filesystem::temp_directory_path()/("penta-refined-branches-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));ode::NativeOptions native;native.cacheDirectory=directory/"kernels";const auto modules=argc>1?std::filesystem::absolute(argv[1]):std::filesystem::path{};
    try{
        const auto fold=model("ode fold(t,real x;real mu){x'=mu-x*x;}");orbits::ContinuationResult branch;branch.rows=2;branch.dimension=branch.physicalDimension=1;branch.kind="equilibrium";branch.key="fixture-fold-branch";branch.states={-.1,.1};branch.parameters={.01,.01};branch.valuesImag={0,0};branch.foldCandidate={0,1};branch.hopfCandidate={0,0};branch.periodDoublingCandidate={0,0};orbits::ContinuationOptions continuation;continuation.minimumParameter=-1;continuation.maximumParameter=1;orbits::CandidateRefinementOptions options;
        auto result=orbits::refineCandidates(fold,1,{.01},branch,continuation,options,native,modules);check(result.markers.size()==1&&result.accepted==1,"A sampled fold is automatically refined by the native augmented corrector");check(std::abs(result.markers[0].parameter)<1e-8&&std::abs(result.markers[0].state[0])<1e-8,"Refined fold matches analytic mu=0,x=0");check(result.markers[0].candidateRow==2&&result.markers[0].bracketFirst==1&&result.markers[0].bracketLast==2,"The marker retains its exact one-based source interval");check(result.sourceKey==branch.key&&!result.markers[0].fingerprint.empty(),"Native structural identity links each marker to its source branch");
        const auto hopf=model("ode hopf(t,real x,real y;real mu){x'=mu*x-y-x*(x*x+y*y);y'=x+mu*y-y*(x*x+y*y);}");branch.dimension=branch.physicalDimension=2;branch.states={0,0,0,0};branch.parameters={-.1,.1};branch.valuesImag={1,-1,1,-1};branch.foldCandidate={0,0};branch.hopfCandidate={0,1};result=orbits::refineCandidates(hopf,1,{0},branch,continuation,options,native,modules);check(result.accepted==1,"A sampled Hopf crossing is automatically refined");check(std::abs(result.markers[0].parameter)<1e-7&&std::abs(result.markers[0].auxiliary-1)<1e-7,"Refined Hopf matches analytic parameter and frequency");
        branch.rows=3;branch.states={0,0,0,0,0,0};branch.parameters={-.1,.1,.2};branch.valuesImag={1,-1,1,-1,1,-1};branch.foldCandidate={0,0,0};branch.hopfCandidate={0,1,1};branch.periodDoublingCandidate={0,0,0};result=orbits::refineCandidates(hopf,1,{0},branch,continuation,options,native,modules);check(result.markers.size()==2&&result.accepted==1&&!result.markers[1].accepted,"Adjacent repeated detections preserve diagnostics and deduplicate one refined root");options.maximumCandidates=1;result=orbits::refineCandidates(hopf,1,{0},branch,continuation,options,native,modules);check(result.omitted==1&&result.markers.size()==1,"Automatic refinements obey the explicit candidate budget");
        const auto flip=model("ode flip(t,real x,real y,real u,real v;real mu){x'=-y+(1-x*x-y*y)*x;y'=x+(1-x*x-y*y)*y;u'=((mu-1)/2+(mu+1)*x/2)*u+((mu+1)*y/2-.5)*v;v'=((mu+1)*y/2+.5)*u+((mu-1)/2-(mu+1)*x/2)*v;}");branch.rows=2;branch.physicalDimension=4;branch.dimension=5;branch.kind="periodic";const double period=2*std::acos(-1.0);branch.states={1,0,0,0,period,1,0,0,0,period};branch.parameters={-.01,.01};branch.periods={period,period};branch.valuesImag.assign(8,0);branch.foldCandidate={0,0};branch.hopfCandidate={0,0};branch.periodDoublingCandidate={0,1};options.maximumCandidates=8;options.refinement.fdAgreement=.01;continuation.periodic.solver.rtol=1e-10;continuation.periodic.solver.atol=1e-12;result=orbits::refineCandidates(flip,1,{0},branch,continuation,options,native,modules);check(result.accepted==1&&std::abs(result.markers[0].parameter)<1e-6,"A periodic branch flip candidate invokes the native Floquet corrector and matches the analytic crossing");check(std::abs(result.markers[0].auxiliary-period)<1e-6,"Automatic periodic refinement retains the physical cycle period");
        runtime::ExecutionOptions execution;execution.dataDirectory=directory;execution.odeCacheDirectory=directory/"kernels";execution.numericModuleDirectory=modules;execution.maxNativeOperations=2000000000;const auto language=runtime::execute(R"(
ode fold(t,real x;real mu){x'=mu-x*x;}
record e=discover(fold,[1],options(parameters=options(mu=1.0),t1=0.1));
record b=continueequilibrium(fold,1,options(parameters=options(mu=1.0),parameter="mu",points=40,step=-0.1,min_step=0.001,max_step=0.1,min_parameter=-0.1,max_parameter=2,auto_refine=1,source_experiment=e,source_run=1));
assert(b.markers.accepted_count==1);assert(b.bifurcation_refined==1);assert(abs(b.markers.parameter(1))<1e-6);assert(b.markers.source_run_id==1);assert(b.markers.source_request_hash==e.request_hash);figure(1);branchplot(b);xlabel("mu");ylabel("x");
)",{},execution);if(!language.ok()){for(const auto& d:language.analysis.diagnostics)std::cerr<<d.code<<": "<<d.message<<'\n';for(const auto& d:language.runtimeDiagnostics)std::cerr<<d.code<<": "<<d.message<<'\n';}check(language.ok(),"Language continuation can request automatic refinement and integrated plotting");std::size_t curves=0;for(const auto& action:language.figureActions)if(action.kind==runtime::FigureActionKind::Plot)curves=action.curves.size();check(curves>=4,"Branch presentation splits stability segments and overlays a two-stroke refined cross");
    }catch(const std::exception& error){std::cerr<<"FAIL after "<<checks<<" checks: "<<error.what()<<'\n';return 1;}
    std::error_code ignored;std::filesystem::remove_all(directory,ignored);std::cout<<checks<<" native continuation/refinement integration checks passed.\n";
}
